var psEqual = function(ps1, ps2) {
  return ps1[0] == ps2[0] && ps1[1] == ps2[1] && ps1[2] == ps2[2];
};

var logScore = function(ps, event) {
  var dist = Categorical({vs: ['A','B','C'], ps: ps});
  return dist.score(event);
};

var alpha = 100;

var getReportedIndexForReward = function(eventRewardA) {

  var eventScore = function(event) {
    return event == 'A' ? eventRewardA : 0;
  };

  var agentDist = Infer({method: 'enumerate', model: function() {
    var reportIndex = uniformDraw([0, 1, 2, 3]);
    var reportPsChoice = reportPs[reportIndex];
    var expectedScore = expectation(Infer({method: 'enumerate', model: function() {
      var isSupervised = !psEqual(reportPsChoice, beliefPs);
      var event = isSupervised ? sample(beliefDist) : sample(Categorical({vs: ['A','B','C'], ps: reportPsChoice}));
      return logScore(reportPsChoice, event) + eventScore(event);
    }}));
    factor(alpha * expectedScore);
    return reportIndex + 1;
  }});

  return agentDist.MAP().val;
};

