var bigrams = function(word) {
  var chars = word.split("")
  return mapIndexed(function(i, c) {
    return chars[i] + chars[i + 1]
  }, chars.slice(0, chars.length - 1))
}

var similarity = function(word1, word2) {
  var b1 = bigrams(word1)
  var b2 = bigrams(word2)
  var shared = filter(function(bg) { return b2.indexOf(bg) > -1 }, b1)
  return (2 * shared.length) / (b1.length + b2.length)
}

