var rand = function() {
  return { uA: flip(0.1), uAB: flip(0.75), uBC: flip(0.75) };
};
var vars = function(rvs) {
  var A = rvs.uA;
  var B = A && rvs.uAB;
  var C = B && rvs.uBC;
  return { A: A, B: B, C: C };
};

var stickiness = 0.53;
var stickyRand = function(actualRVs) {
  var freshRVs = rand();
  return {
    uA: flip(stickiness) ? actualRVs.uA : freshRVs.uA,
    uAB: flip(stickiness) ? actualRVs.uAB : freshRVs.uAB,
    uBC: flip(stickiness) ? actualRVs.uBC : freshRVs.uBC
  };
};

var ANSWER = Infer({method: 'enumerate', model: function() {
  var actualRVs = rand();
  var actualWorld = vars(actualRVs);
  condition(actualWorld.A && actualWorld.B && actualWorld.C);
  var cfRVs = stickyRand(actualRVs);
  var cfWorld = vars(cfRVs);
  condition(!cfWorld.B);
  return cfWorld.A;
}});

