// Generate the state space given a number of bins: bin-center representative values
var stateGen = function(numberBins) {
  var binSize = 1 / numberBins
  var binArray = _.range(0, numberBins)
  return map(function(x){return Math.round(((binSize/2)+(binSize*x))*100)/100}, binArray)
}

// Power set helper (nonempty subsets filtered below)
var powerset = function(set){
  if(set.length==0){
    return [set]
  }
  var r = powerset(set.slice(1))
  var element = [set[0]]
  var new_r = r.concat(map(function(x){ return element.concat(x) }, r))
  return new_r
}

var allstates = stateGen(5)
var powersetStates = filter(function(x){return x.length>0}, powerset(allstates))

var statePrior = function() {
  return uniformDraw(powersetStates)
}

// Turn a raw event-slot subset into 5 named indicator flags, slot1 (lowest value) .. slot5 (highest)
var indicatorState = function(state) {
  return {
    slot1: state.indexOf(allstates[0]) > -1,
    slot2: state.indexOf(allstates[1]) > -1,
    slot3: state.indexOf(allstates[2]) > -1,
    slot4: state.indexOf(allstates[3]) > -1,
    slot5: state.indexOf(allstates[4]) > -1
  }
}

var utterances = ["prog", "impf", ""]
var cost = {
  "prog": 5,
  "impf": 1,
  "": 100
}
var utterancePrior = function() {
  var uttProbs = map(function(u) {return Math.exp(-cost[u]) }, utterances)
  return categorical({ps: uttProbs, vs: utterances})
}

// All ordered pairs (thetaR, thetaT) with thetaT >= thetaR over the shared grid
var possibleThetas = [0.4,0.5,0.6,0.7,0.8,0.9,1]
var thetas = _.flatten(map(function(a){
  return map(function(b){ return [a, b] }, filter(function(b){ return b>=a }, possibleThetas))
}, possibleThetas), true)

var thetasPrior = function(){
  return uniformDraw(thetas)
}

var thetaBins = function(numberBins, theta) {
  var binSize = theta / numberBins
  var binArray = _.range(0, numberBins)
  var binPop = map(function(x){return (binSize)+(binSize*x)}, binArray)
  return [0].concat(binPop)
}

var meaningFn = function(state, bins, index, stateSoFar){
  var stateSoFar = stateSoFar == undefined ? [] : stateSoFar
  if (index != bins.length-1){
    var inBin = any(function(x){return x>bins[index] && x<=bins[index+1]}, state)
    return meaningFn(state, bins, index+1, stateSoFar.concat(inBin))
  }
  else {
    return all(function(x){return x==true}, stateSoFar)
  }
}

var meaning = function(utterance, binsR, binsT, state) {
  return utterance == "prog" ? meaningFn(state, binsR, 0) :
         utterance == "impf" ? meaningFn(state, binsT, 0) :
         true
}

