var linearScore = function(dist, event) {
  // not incentive-compatible!
  return Math.exp(dist.score(event));
};

var logScore = function(dist, event) {
  return dist.score(event);
};

var quadraticScore = function(dist, event) {
  var squares = map(function(x){ return Math.pow(Math.exp(dist.score(x)), 2); }, dist.support());
  return 2 * Math.exp(dist.score(event)) - sum(squares);
};

