    var reportDist = candidateReports[reportIndex];
    var expectedScore = expectation(Infer({method: 'enumerate'}, function(){
      var event = sample(beliefDist);
      return scoreFn(reportDist, event);
    }));
    factor(alpha * expectedScore);
    return reportIndex + 1;
  });
};

