var bins = _.range(0.1, 1.1, 0.1);
var DiscreteBetaProbs = cache(function(g, d){
  var a =  g * d, b = (1-g) * d;
  var betaPDF = function(x){
    return Math.pow(x, a-1)*Math.pow((1-x), b-1)
  }
  return map(betaPDF, bins);
})

